/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «مقدمة في علم العلاقات الدولية» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["ir"]={"id":"ir","title":"مقدمة في علم العلاقات الدولية","sub":"","author":"نايف بن نهار","coauthors":[],"translator":"","publisher":"مؤسسة وعي","year":"2017","edition":"","series":"","lead":"مقرر تمهيدي ميسر يبني مباحث العلاقات الدولية كلها على تعريف واحد، ويشبه الساحة الدولية بملعب كرة قدم له لاعبون ومدرب وحكم ومحللون وجمهور. يقول المؤلف في مقدمته: «فقد عرّفتُ علم العلاقات الدولية بأنه العلم الذي يدرس مكوّنات المجتمع الدولي ذات التأثير السياسي» (ص 5).","audience":"طلاب المرحلة الجامعية الأولى في العلوم السياسية، ومعلمو الدراسات الاجتماعية، والقارئ المهتم بالشأن الدولي","bio":"","chapters":[{"k":"c1","t":"الفصل الأول: مقدّمات في العلاقات الدولية","q":"ما علم العلاقات الدولية، ومن أين بدأ، وما قواعده الحاكمة؟","essence":"ملعب دولي له لاعبون ومدرب وحكم","kw":["المجتمع الدولي","معاهدة ويستفاليا","المساواة في السيادة"],"sections":[{"t":"مكوّنات العلاقات الدولية","pg":12,"key":"المدرّب هو الأمم المتحدة، فكما أنَّ المدرّب في كرة القدم يعطي تعليماته للاعبين في أرض الملعب، كذلك الأمم المتحدة تعطي تعليماتها للاعبين الدوليين في المجتمع الدولي.","p":["أمَّا الحَكَم فهو القانون الدولي الذي ينظّم اللعبة، فكما أنَّ لكرة القدم قانوناً ينظّم سلوك اللاعبين داخل الملعب ومن يخالفه يُعاقب، كذلك يوجد قانون دولي ينظّم سلوك اللاعبين الدوليين، ومَن يُخالفه يُعرّض نفسَه للعقوبة."],"items":[{"h":"اللاعبون","x":"كانت الدولة اللاعب الوحيد قديما، واليوم صار اللاعبون الأساسيون ثلاثة: الدول، والمنظمات الدولية، والشركات متعددة الجنسيات."},{"h":"المدرّب والحكم","x":"الأمم المتحدة تصدر التعليمات وقد لا يلتزم بها اللاعبون، والقانون الدولي ينظم اللعبة ويعاقب المخالف."},{"h":"المحللون والمنظرون","x":"التحليلات الدولية تصف وتتنبأ، مثل نهاية التاريخ وصدام الحضارات، والنظريات الدولية تقترح ما يحسن العلاقات، مثل السلام الديمقراطي والحكومة العالمية."},{"h":"الجمهور","x":"الرأي العام، أي شعوب العالم، يؤيد أو ينتقد ولا يدخل الملعب، وقد أجّل المؤلف الحديث عنه إلى طبعات قادمة."}]},{"t":"تعريف علم العلاقات الدولية","pg":15,"key":"لكن التعريف الذي نعتمده في هذا الكتاب هو أنه العلم الذي يدرس مكوّنات المجتمع الدولي ذات التأثير السياسي.","p":["ويتبيّن من ذلك أنَّ الكيانات التي تعمل في إطار الدولة فقط لا تدخل ضمن اهتمامات علم العلاقات الدولية، مثل الوزارات والأفراد ومؤسسات المجتمع المدني الداخلية، وإنما تندرج ضمن العلوم السياسية."],"items":[{"h":"مكوّنات المجتمع الدولي","x":"ما يعمل على الصعيد الدولي من دول ومنظمات وشركات، وتشمل العلاقات البينية والكيانات نفسها."},{"h":"ذات التأثير السياسي","x":"يدخل كل مكوّن له أثر سياسي ولو كان اقتصاديا كالشركات، ويخرج ما لا أثر سياسيا له كبطولة كأس العالم."},{"h":"الفاعل يعرف بتأثيره","x":"كل من يؤثر دوليا ويصنع توجهات السياسات الخارجية فاعل سياسي ولو كان فردا."}]},{"t":"نشأة العلم وإشكالية المصطلح","pg":18,"key":"وبذلك يكون علم العلاقات الدولية علماً حديثاً إذا ما قورن بالعلوم الاجتماعية الأخرى كالسياسة والاقتصاد والاجتماع.","p":["أما مصطلح \"الشؤون الدولية\" فهو غير مانع، فهو مصطلح عام جداً يسمح بدخول أشياء لا علاقة لها بعلم العلاقات الدولية"],"items":[{"h":"النشأة","x":"كان يدرس تحت مظلة التاريخ الدبلوماسي أو العلوم السياسية، وقيل إن أول كرسي له أسس في جامعة ويلز عام 1919، وقيل لم يعترف به علما إلا بعد الحرب العالمية الثانية."},{"h":"سبب الظهور","x":"خرج العلم استجابة لحاجة الواقع بعد أن ذاقت أوروبا مرارة الحرب، لا نتيجة تنظير عقلي مجرد."},{"h":"نقد التسميات","x":"الشؤون الدولية غير مانع، والعلاقات الدولية غير جامع ولا مانع، والسياسة الخارجية جزء من العلم لا مساوية له."},{"h":"الاختيار","x":"السياسة الدولية أنسب التسميات، لكن العلاقات الدولية أشهرها، ولذلك اختارها المؤلف عنوانا."}]},{"t":"تاريخ العلاقات الدولية في ست مراحل","pg":21,"key":"وإذا جعلنا معاهدة ويستفاليا هي نقطة البداية لتاريخ العلاقات الدولية الحديث فإنَّه يمكن أن نحدد ست مراحل مرَّت بها العلاقات الدولية","p":["الخصيصة الأولى: أنه لم يكن في الساحة الدولية سوى لاعب واحد، وهو الدولة. فلم تكن هناك منظمات دولية ولا شركات متعددة الجنسيات."],"items":[{"h":"من ويستفاليا إلى الحرب الأولى","x":"من 1648 إلى 1914: لاعب واحد هو الدولة، ونظام متعدد الأقطاب، ومن أحداثها الثورات الإنجليزية والأمريكية والفرنسية وثورات 1848."},{"h":"الحرب العالمية الأولى","x":"شرارتها اغتيال ولي عهد النمسا في سراييفو، وانتهت بانهيار أربع إمبراطوريات، وفيها الثورة البلشفية وسايكس بيكو ووعد بلفور."},{"h":"ما بعد الحرب الأولى","x":"نشوء عصبة الأمم، وبروز الأيدلوجيات الشمولية، والكساد الكبير وظهور المذهب الكينزي، وإلغاء الخلافة في إسطنبول."},{"h":"الحرب العالمية الثانية","x":"إذلال فرساي مهّد لهتلر، وتحالف السوفييت مع الغرب خوفا من عدو مشترك، وخرجت الولايات المتحدة وحدها منتشية."},{"h":"الحرب الباردة","x":"نظام ثنائي القطبية، وظهور فعلي للمنظمات والشركات، وحروب بالوكالة، وأعظم إنجازاتها أنها لم تتحول إلى حرب ساخنة."},{"h":"ما بعد الحرب الباردة","x":"تفردت الولايات المتحدة بالهيمنة وصار النظام أحادي القطبية."}]},{"t":"القواعد الحاكمة للعلاقات الدولية","pg":40,"key":"السيادة هي أن تكون الدولة قادرة على التعبير عن إرادتها داخليًا وخارجيًا.","p":["فهناك تساوٍ تام بين الدول في امتلاك السيادة."],"items":[{"h":"القاعدة الأولى: المساواة في السيادة","x":"ترسخت بعد ويستفاليا ونص عليها الميثاق، ويترتب عليها عدم جواز التدخل في الشؤون الداخلية لدولة أخرى."},{"h":"القاعدة الثانية: منع الحلول العسكرية","x":"تحرم القوة والتهديد بها في حل الخلافات، فخالفها النظام العراقي مع الكويت، والتزمت بها قطر والبحرين بلجوئهما إلى محكمة العدل الدولية."},{"h":"القاعدة الثالثة: الحل العسكري وفقا للقانون","x":"يجوز في حالتين: الدفاع عن النفس إلى أن يتخذ مجلس الأمن التدابير اللازمة، والمشاركة في حفظ السلم من خلال مجلس الأمن."}]}],"quiz":[{"q":"في تشبيه الكتاب العلاقات الدولية بملعب كرة قدم، من يؤدي دور الحَكَم؟","o":["القانون الدولي","الأمم المتحدة","جمهور الشعوب","المحكمة الدولية"],"why":"أمَّا الحَكَم فهو القانون الدولي الذي ينظّم اللعبة","pg":12},{"q":"بطولة كأس العالم حدث يقع على صعيد المجتمع الدولي، فلماذا لا تعد من مباحث علم العلاقات الدولية؟","o":["لأنها لا أثر سياسيا لها من حيث الأصل","لأنها تقام داخل حدود دولة واحدة بعينها","لأن منظمها ليس دولة ذات سيادة","لأنها نشاط اقتصادي وتجاري بحت"],"why":"لكنه حدثٌ ليس له تأثير سياسي من حيث الأصل، ولذلك لا يُعدُّ من مباحث علم العلاقات الدولية.","pg":16},{"q":"أي التسميات يراها المؤلف أكثر مناسبة لهذا العلم من حيث الدلالة؟","o":["السياسة الدولية","العلاقات الدولية","الشؤون الدولية","السياسة الخارجية"],"why":"أما مصطلح السياسة الدولية فهو الأكثر مناسبةً من بين هذه المصطلحات","pg":19},{"q":"ما الذي ميّز المرحلة الممتدة من معاهدة ويستفاليا إلى الحرب العالمية الأولى؟","o":["لاعب دولي واحد ونظام متعدد الأقطاب","لاعبون متعددون ونظام متعدد الأقطاب","لاعب دولي واحد ونظام ثنائي القطبية","هيمنة قطب واحد وانتشار المنظمات الدولية"],"why":"الخصيصة الأولى: أنه لم يكن في الساحة الدولية سوى لاعب واحد، وهو الدولة.","pg":21},{"q":"اختلفت دولتان على جزر، فرفعتا الأمر إلى محكمة العدل الدولية وقبلتا حكمها. أي قاعدة من القواعد الحاكمة طبقتاها؟","o":["منع الحلول العسكرية في الخلافات","جواز الحل العسكري وفقا للقانون","المساواة في السيادة بين الدول","حق الدفاع الفردي والجماعي عن النفس"],"why":"في حين كان النظامان البحريني والقطري ملتزمين بهذه القاعدة حين اختارا أن يحلا خلافهما حول الجزر من خلال الوسائل السلمية وليس القوة","pg":43}]},{"k":"c2","t":"الفصل الثاني: اللاعبون الدوليون","q":"من اللاعبون الأساسيون في الساحة الدولية، وما خصائص كل منهم؟","essence":"الدولة والمنظمات والشركات لاعبون ثلاثة","kw":["الدولة","الشخصية القانونية","الشركات متعددة الجنسيات"],"sections":[{"t":"ويستفاليا وبداية الدولة الحديثة","pg":54,"key":"هذه النتائج السياسيّة كانت النواة التاريخية لمفهوم الدولة الوطنية القوميّة","p":["أي أنَّ أساس الدولة الحديثة بصورتها القانونية الحالية يعود إلى هذه المعاهدة التي أقرَّت وجود الدول واستقلالها بطابعها القومي."],"items":[{"h":"ضرورة الدولة","x":"الإنسان اجتماعي بطبعه، فلا بد من كيان يفصل في منازعاته، ويقابل ذلك رأي الماركسيين والأناركيين في الدولة بوصفها شرا."},{"h":"المعاهدة","x":"عقدت عام 1648 وأنهت حروبا دينية بين الكاثوليك والبروتستانت دامت ثلاثين عاما، وأقرت الحرية الدينية."},{"h":"نتائجها السياسية","x":"استقلال هولندا وسويسرا، وتأكيد استقلال أكثر من ثلاثمئة وخمسين ولاية في شؤونها الخارجية."}]},{"t":"معنى الدولة وعناصرها","pg":55,"key":"إذن يمكن القول إنَّ الدولة هي: السلطة التي تحكم شعبًا محددًا على أرضٍ محددة.","p":["إذ السلطة بلا سيادة خارجية تسمى \"حكومة\" ولا تسمى \"دولة\"."],"items":[{"h":"الإقليم","x":"بري وبحري وجوي، وانتهى الجدل في البحر الإقليمي باتفاقية 1982 على 12 ميلا بحريا حدا أقصى."},{"h":"الشعب","x":"له معنى قانوني هو حملة الجنسية، ومعنى سياسي هو المؤهلون للمشاركة السياسية، ولا يشترط فيه التجانس كالأمة."},{"h":"الحكومة","x":"تستعمل استعمالا عاما يشمل السلطات الثلاث، وخاصا يراد به السلطة التنفيذية."},{"h":"السيادة","x":"داخلية بفرض الإرادة على كل الأراضي، وخارجية بعدم الخضوع لوصاية، ولذلك كانت تسمى حكومة قطر لا دولة قطر قبل استقلالها عام 1971."}]},{"t":"الشرعية الدولية وأنواع الدولة","pg":62,"key":"فالاعتراف الدولي عمل كاشف وليس عملاً مؤسسًا","p":["ونحن في هذا الكتاب اعتمدنا الموقف الثاني، فالاعتراف الدولي عمل كاشف وليس عملاً مؤسسًا، ولذلك لم نجعل شرط \"الشرعية الدولية\" من الشروط الأساسية للدولة، بل جعلناه شرطًا كماليًا."],"items":[{"h":"فقدان السيادة","x":"من فقد السيادة الداخلية فهو دولة فاشلة، ومن فقد الخارجية فهو دولة ناقصة السيادة: محمية أو تحت الانتداب."},{"h":"الشرعية الدولية","x":"اعتراف الأمم المتحدة شرط لاكتمال الدولة لا لتأسيسها، فتايوان دولة وإن لم تعترف بها المنظمة، ولها درجتان: ناقصة وتامة."},{"h":"شرعية السلطة","x":"رضا الشعب شرعية داخلية، وقبول المجتمع الدولي للحكومة شرعية خارجية، وليست الداخلية شرطا لنشوء الدولة."},{"h":"باعتبار توزيع السلطة","x":"دولة بسيطة موحدة كقطر، وفيدرالية كالإمارات والولايات المتحدة، وكونفدرالية لم يعد لها مثال إلا ما يقاربها كالاتحاد الأوروبي."}]},{"t":"المنظمات الدولية","pg":68,"key":"يمكن أن نُعرّف المنظمة الدولية بأنها كيان دولي يؤسس على اتفاق وله شخصية قانونية مستقلة دولية.","p":["ومن حيث المجال لا يوجد مجال في الحياة إلا وهناك منظمّة دولية تعتني به."],"items":[{"h":"الخصائص الثلاث","x":"كيان دولي يتجاوز حدود دولة واحدة، ينشأ عن اتفاق قد يسمى عهدا أو ميثاقا أو دستورا، وله شخصية قانونية مستقلة. ولا يشترط المؤلف أن يكون المؤسسون دولا."},{"h":"النشأة","x":"أول منظمة دولية الاتحاد الدولي للبرق عام 1865، ثم اتحاد البريد العالمي، ثم عصبة الأمم، ثم الأمم المتحدة."},{"h":"الشخصية القانونية","x":"حسمتها محكمة العدل الدولية عام 1949 بعد مقتل الكونت برنادوت، ويترتب عليها إبرام الاتفاقيات والذمة المالية المستقلة وأهلية التقاضي."},{"h":"أقسامها","x":"باعتبار الانفتاح، وباعتبار السلطة (استشارية أو ملزمة)، وباعتبار المجال (عامة أو متخصصة)، وباعتبار الأعضاء (حكومية أو غير حكومية)."}]},{"t":"الشركات متعددة الجنسيات","pg":80,"key":"الشركات متعددة الجنسيات هي: كيان دولي تجاري خاص له فروع في أكثر من دولتين مرتبطة بالشركة الأم.","p":["ولذلك ثمة اعتقاد بأنَّ اللاعب الدولي الأوّل والأهم ليس هو الدولة كما يعتقد الواقعيون، وليس النظام الدولي كما يعتقد الليبراليون، وإنّما هو الشركات متعددة الجنسيات"],"items":[{"h":"القيود الأربعة","x":"كيان دولي، وتجاري يهدف إلى الربح، وخاص لا تملكه دول، ومرتبط بإدارة الشركة الأم."},{"h":"أسباب الظهور","x":"التخلص من كلفة النقل والحدود الجمركية، واستثمار الفائض النقدي في أسواق جديدة."},{"h":"المزايا للدول المستضيفة","x":"توفير فرص العمل، وسد الفجوة التكنولوجية والعلمية، والمساعدة في التنمية الاقتصادية."},{"h":"الانتقادات","x":"استغلال الطبقات الفقيرة، وإعاقة تنمية العالم الثالث، والتدخل في القرار السياسي، وعدم خدمة البلد الأصلي."}]}],"quiz":[{"q":"كيان له شعب وأرض وحكومة، لكنه لا يملك قراره الخارجي لخضوعه لانتداب دولة أخرى. ماذا يسمى بحسب الكتاب؟","o":["دولة ناقصة السيادة","دولة فاشلة داخليا","دولة اتحادية فيدرالية","دولة بسيطة موحدة"],"why":"أما إذا فقدت الدولة سيادتها الخارجية لظرف من الظروف فإنها تسمى دولة ناقصة السيادة، أي غير مستقلة.","pg":60},{"q":"ما منزلة اعتراف الأمم المتحدة بالدولة في الموقف الذي اعتمده المؤلف؟","o":["شرط كمالي يكشف عن الدولة ولا ينشئها","شرط أساسي لا تقوم الدولة من دونه","إجراء شكلي لا أثر له في الوضع القانوني","عنصر مادي خامس من عناصر الدولة"],"why":"فالاعتراف الدولي عمل كاشف وليس عملاً مؤسسًا","pg":62},{"q":"لماذا رد المؤلف على من اشترطوا أن تؤسس المنظمة الدولية باتفاق بين دول؟","o":["لأن أطباء بلا حدود منظمة دولية أنشأها أفراد","لأن الدول لا تملك شخصية قانونية دولية مستقلة","لأن محكمة العدل الدولية قضت بذلك صراحة","لأن العضوية فيها مقصورة على الأفراد والجمعيات"],"why":"فليس من شرط المنظمة الدولية أن تكون ناشئة عن اتفاق الدول، بل قد تكون ناشئة عن اتفاق منظمات أو جمعية أو حتى أفراد.","pg":69},{"q":"منظمة الأرصاد الجوية تقدم الرأي للدول دون أن تلزمها بشيء. كيف تصنف باعتبار سلطتها؟","o":["منظمة استشارية لا سلطة لها","منظمة ذات سلطة إلزامية","منظمة عامة غير متخصصة المجال","منظمة غير مفتوحة العضوية"],"why":"القسم الأول: منظمّات لا سلطة لها؛ وهي المنظمات الاستشارية التي لا تملك سوى تقديم الرأي والمشورة للدول","pg":76},{"q":"بنك التنمية الإسلامي كيان اقتصادي تجاري عابر للقارات، فلماذا لا يصنف من الشركات متعددة الجنسيات؟","o":["لأن ملكيته تابعة لدول لا لأفراد","لأنه لا يهدف إلى الربح أصلا","لأن فروعه لا تتبع إدارة أما واحدة","لأنه لا ينتشر في أكثر من دولتين"],"why":"لأنَّ ملكيّته تابعة لدول، وليست تابعة لأفراد.","pg":81}]},{"k":"c3","t":"الفصل الثالث: مدارس العلاقات الدولية","q":"كيف تفسر المدارس الكبرى سلوك الدول، وما الموقف الإسلامي من ذلك؟","essence":"القوة والقانون والاقتصاد، وموقف إسلامي رابع","kw":["الواقعية","المثالية","الماركسية"],"sections":[{"t":"المدرسة الواقعية","pg":95,"key":"ومن هنا يرى الواقعيون أن عامل القوة هو العامل المركزي في العلاقات الدولية","p":["وهذا ما يفسّر كون الدول تسعى إلى الحصول على القوة وزيادتها بنحو دائم؛ لأنها هي المسؤول الأول والأخير عن أمنها."],"items":[{"h":"المنطلق","x":"الأصل في الفرد الشر والأنانية، والدولة انعكاس للفرد، وجذورها الحديثة عند مكيافيللي وهوبز."},{"h":"النظام الدولي فوضى","x":"لا سلطة تعلو الدولة وتحميها، فعليها أن تعتمد على نفسها وتعظّم قوتها."},{"h":"الغاية والآلية","x":"تعظيم المصلحة الوطنية بالقوة والأمن، والحرب عندهم حالة طبيعية لأن تعارض المصالح وقود الحروب."},{"h":"المبادئ والمصالح","x":"لا قيود أخلاقية حين تتعارض مع المصلحة، ومثال ذلك الانقلاب على حكومة مصدق في إيران عام 1953."},{"h":"الانتقادات","x":"جعلت القوة محددا وحيدا، وتعكس الرؤية الغربية، وتعجز عن تفسير التعاون الواسع بين دول كألمانيا وفرنسا وبريطانيا."}]},{"t":"المدرسة المثالية","pg":100,"key":"فإذا كانت المدرسة الواقعية تستند إلى مركزيَّة القوَّة والمصلحة فإنَّ المدرسة المثالية تستند إلى مركزيَّة المبدأ والقانون.","p":["والمثالية لا تختلف مع الواقعية في أهمية الأمن للدول، لكنها تختلف في أنَّ القوة وتضخيمها ليست هي الآلية المناسبة لتحقق الدول أمنها"],"items":[{"h":"المنطلق","x":"الأصل في الإنسان الخير والعقلانية، ولذلك تسمى أيضا الليبرالية، ومن أبرز ممثليها وودرو ويلسون صاحب فكرة عصبة الأمم."},{"h":"النظام الدولي","x":"تقر بوجود الفوضى لكنها لا تراها مؤثرة كثيرا، وتعول على القانون الدولي والمنظمات والاعتماد المتبادل، ومثالها الاتحاد الأوروبي."},{"h":"الانتقادات","x":"تقوم على تصور لا يشكل الواقع جزءا منه، وتغفل أن الدول لا تقبل أن تكون أضعف من خصومها."},{"h":"وحدة التحليل","x":"الدولة عند الواقعية والنظام الدولي عند المثالية، والخلاف يتقلص إذا عددنا المثالية معيارية والواقعية وصفية."}]},{"t":"المدرسة الماركسية","pg":109,"key":"وبناءً على ما سبق، يرى الماركسيون أن الدافع الوحيد الذي يُحرّك سلوك الدولة هو الدافع الاقتصادي.","p":["ومن هنا فإنَّ الماركسيين لا يؤمنون بأن التغيير يأتي من خلال المنظمات الدولية أو الوسائل الدبلوماسية وإنما من خلال الوسائل الثوريّة فقط."],"items":[{"h":"الطبقتان","x":"البروليتاريا الكادحة التي تبيع قوة عملها، والبرجوازية الغنية التي تشتري جهدها."},{"h":"الدولة","x":"شر يعبر عن التمايز الطبقي، يقبل وجوده مرحلة تاريخية ثم يتلاشى حين يصل المجتمع إلى الحالة الشيوعية."},{"h":"النظام الدولي","x":"خاضع للهيمنة الرأسمالية الإمبريالية وتسيطر عليه الشركات العالمية الكبرى."},{"h":"الانتقادات","x":"حصرت دوافع السلوك الدولي في الاقتصاد، وجعلت التغيير الثوري مطلقا مع أنه نسبي بين المجتمعات."}]},{"t":"الموقف الإسلامي من العلاقات الدولية","pg":112,"key":"واخترنا التعبير ب \"الموقف الإسلامي\" وليس \"المدرسة الإسلامية\"؛ لأنَّ الإسلام ليس مدرسة يتعاقب في تكوينها العلماء والمفكرون","p":["وكل حكم من هذه الأحكام غايته أن يعود المشهد الدولي إلى الغاية الإلهية الأولى، وهي التعارف الحضاري."],"items":[{"h":"الفرد والدولة","x":"للإنسان قدرة على الخير والشر، والغالب ميله إلى التعدي، والدولة أداة بيده فاحتمال التعدي فيها أكبر."},{"h":"حالات استعمال القوة","x":"الدفاع عن النفس، ودرء الفتنة أي منع الصد عن الدين بالقوة، ونقض المعاهدات مرارا، وما سوى ذلك اعتداء."},{"h":"القوة والعدل","x":"جناحان لا تقلع المصلحة إلا بهما، والقوة تعد لتحقيق توازن القوى والردع دون استعمالها."},{"h":"المبدأ والمصلحة","x":"لا يجوز الإخلال بالمبدأ طمعا بمصلحة غير استراتيجية، ولا يجب الالتزام به إن أخل بمصلحة استراتيجية تمس وجود الدولة."}]}],"quiz":[{"q":"ترى إحدى المدارس أن المنظمات الدولية وما ينشأ عنها هي اللاعب الأكثر أهمية في النظام الدولي. أي مدرسة هي؟","o":["المدرسة المثالية","المدرسة الواقعية","المدرسة الماركسية","الواقعية الدفاعية"],"why":"فإن المثالية لا تقبل ذلك، وترى أن المنظمات الدولية وما ينشأ عنها هي اللاعب الأكثر أهمية في النظام الدولي.","pg":91},{"q":"الأفراد في المجتمع لا يحملون السلاح في الطرقات، بينما تتسابق الدول إلى شراء الأسلحة. بم تفسر الواقعية ذلك؟","o":["بغياب سلطة دولية عليا قادرة على حمايتها","بضغط شركات السلاح الكبرى على صناع القرار","برغبتها في نشر قيمها الديمقراطية","بالتزامها بقرارات مجلس الأمن الدولي"],"why":"هنا تبرز إجابة المدرسة الواقعية التي ترى أنَّ الدولة هي المسؤولة عن حفظ أمنها؛ لأنه لا يوجد جهاز أو كيان في النظام الدولي يعلو عليها وقادر على حمايتها","pg":94},{"q":"ما الذي يجمع وجوه النقد الموجهة إلى المدرسة المثالية؟","o":["أنها لا تعطي القوة وزنها اللائق بها","أنها تحصر سلوك الدولة في الاقتصاد","أنها تجعل القوة المحدد الوحيد للسلوك","أنها تنكر وجود القانون الدولي أصلا"],"why":"والجامع المشترك في نقد المدرسة المثالية أنها لا تعطي القوة وزنها اللائق بها في العلاقات الدولية.","pg":104},{"q":"فسّر محلل سلوك ألمانيا في زمن هتلر بالمصالح الاقتصادية وحدها. بم ينتقد الكتاب هذا التفسير الماركسي؟","o":["بإغفاله دافع الأيدلوجيا النازية","بمبالغته في دور المنظمات الدولية","بإنكاره أثر الفرد في صنع القرار","بتعويله على القانون الدولي وحده"],"why":"فعلى سبيل المثال لا يمكن أن نفهم سلوك ألمانيا في زمن هتلر إذا قصرنا الأمر على الدافع الاقتصادي وحده","pg":109},{"q":"دولة التزمت بقضية مبدئية، ثم صار الالتزام يعرض وجودها السياسي للخطر. ما الحكم في المنطق الإسلامي كما يعرضه الكتاب؟","o":["عليها أن تنسحب منه حفظا لمصلحتها","يجب الثبات عليه مهما كانت العواقب","يجوز تركه لأي مكسب نفطي أو مادي","يرجع في أمره إلى قرار مجلس الأمن الدولي"],"why":"لكن في المقابل لا يجب الالتزام بالمبدأ إذا كان يخل بمصلحة استراتيجية للدولة","pg":119}]},{"k":"c4","t":"الفصل الرابع: مستويات التحليل في العلاقات الدولية","q":"من أين ننطلق لنحلل سلوك دولة ما تحليلا متكاملا؟","essence":"الفرد ونظام الدولة والنظام الدولي","kw":["صانع القرار","النظام السياسي","القطبية"],"sections":[{"t":"لماذا ثلاثة مستويات؟","pg":123,"key":"إذا اخترنا عنصرًا واحدًا فقط من تلك العناصر عند ممارسة العملية التحليلية فإنَّ تحليلنا سيكون قاصرًا","p":["فلا بد من مراعاة جميع تلك العناصر حتى نخرج بتحليل سياسي متكامل."],"items":[{"h":"المستويات","x":"الفرد، ونظام الدولة، والنظام الدولي، والنظام الإقليمي مندرج في الدولي."},{"h":"أهمها","x":"تتكامل المستويات، لكن الثالث أكثرها أهمية لأن غياب سلطة عليا يترك المجال مفتوحا للقوة."}]},{"t":"المستوى الأول: الفرد","pg":125,"key":"إذًا مصطلح \"الفرد\" أكثر دقةً من مصطلح الحاكم أو الرئيس؛ لأنَّه ليس بالضرورة أن يكون الحاكم هو صانع القرار","p":["ونقول إنَّ شخصية صانع القرار والأيدلوجيا التي يتبناها يساهمان في التنبؤ بسلوك الدولة السياسي."],"items":[{"h":"صانع القرار","x":"قد لا يكون الرئيس الرسمي، بل شخصيات نافذة حوله."},{"h":"مثال","x":"شخصية بيل كلينتون غير عدائية وليبرالية، بخلاف جورج بوش ذي النزعة العدائية المتأثرة بعوامل دينية واقتصادية."},{"h":"تفسير النزعة","x":"منهم من يردها إلى الطبيعة البشرية، ومنهم من يردها إلى التنشئة، كنظريات فرويد ودولارد ولورنز."}]},{"t":"المستوى الثاني: نظام الدولة","pg":127,"key":"لكنه لا يستطيع ترجمة تلك النزعة إلى واقع عملي بسبب أنَّ نظام بلاده السياسي لا يسمح بذلك","p":["لأنَّ رئيس الدولة في الجمهورية اللبنانية لا يملك سلطة تنفيذية، وإنما هو مجرد رمز للدولة ويتمتع بمهام شرفية"],"items":[{"h":"لبنان","x":"النظام برلماني، فرئيس الجمهورية رمز، ورئيس الوزراء يحتاج إلى موافقة البرلمان."},{"h":"إيران","x":"الرئيس لا يملك قرار السلم والحرب، فهو من صلاحيات الولي الفقيه."},{"h":"الخلاصة","x":"ندرس النظم السياسية لنعرف مواطن السلطة الفعلية من الشكلية."}]},{"t":"المستوى الثالث: النظام الدولي","pg":129,"key":"ويُعرِّف السياسيون الدولة المهيمنة بأنها الدولة التي تعد الأقوى في النظام الدولي بحيث تهدد هي الدول الأخرى دون أن تستطيع أي دولة تهديدها.","p":["فعلى ذلك، فإنَّ الولايات المتحدة كانت دولة \"عظمى\" طوال مرحلة الحرب الباردة، لكنها لم تكن دولة \"مهيمنة\"؛ لأنها لم تكن قطبًا وحيدًا"],"items":[{"h":"أنواع القطبية","x":"أحادية كما بعد سقوط الاتحاد السوفيتي، وثنائية كالحرب الباردة، ومتعددة كمنتصف القرن التاسع عشر والوقت الحاضر."},{"h":"أثرها في التحليل","x":"الأحادية تقلل تمرد الدول الصغيرة والمتوسطة، والمتعددة تعقد التحليل لتلاعب الدول بالتوازنات."},{"h":"تطبيق جامع","x":"لو قصفت كوريا الشمالية اليابان: ننظر في شخصية الرئيس الأمريكي، وفي موقف الكونغرس، وفي قدرة الصين وحلفائها على الردع."}]}],"quiz":[{"q":"لماذا فضّل المؤلف مصطلح \"الفرد\" على \"الحاكم\" في تسمية المستوى الأول؟","o":["لأن صانع القرار قد يكون غير الحاكم الرسمي","لأن الحاكم لا أثر له في رسم السياسة الخارجية","لأن الفرد يشمل أبناء الشعب كله لا القائد","لأن الدساتير الحديثة لا تعرف لقب الحاكم"],"why":"السبب في ذلك يعود إلى أنَّ \"صانع القرار\" ليس بالضرورة أن يكون هو حاكم الدولة","pg":125},{"q":"صرّح رئيس الجمهورية اللبنانية بموقف حاد من قضية ما. لماذا لا يعول المحلل كثيرا على هذا التصريح؟","o":["لأن النظام برلماني ومهامه شرفية","لأن شخصيته ليست عدائية بطبعها","لأن لبنان يخضع لهيمنة قطب دولي واحد","لأن البرلمان لا يملك أي صلاحية"],"why":"لأنَّ رئيس الدولة في الجمهورية اللبنانية لا يملك سلطة تنفيذية، وإنما هو مجرد رمز للدولة ويتمتع بمهام شرفية","pg":127},{"q":"كانت الولايات المتحدة في الحرب الباردة دولة عظمى لا مهيمنة. ما الذي ينقصها لتوصف بالهيمنة؟","o":["أن تكون القطب الوحيد الذي لا يهدده أحد","أن تمتلك سلاحا نوويا رادعا لخصومها","أن تكون عضوا دائما في مجلس الأمن","أن تقود حلفا عسكريا واسعا في قارة أوروبا"],"why":"فعلى ذلك، فإنَّ الولايات المتحدة كانت دولة \"عظمى\" طوال مرحلة الحرب الباردة، لكنها لم تكن دولة \"مهيمنة\"؛ لأنها لم تكن قطبًا وحيدًا","pg":129},{"q":"أي مستويات التحليل يعده الكتاب الأكثر أهمية مع تكاملها؟","o":["مستوى النظام الدولي","مستوى الفرد صانع القرار","مستوى النظام السياسي","مستوى المجتمع المحلي"],"why":"فإن المستوى الثالث هو الأكثر أهمية من بينها","pg":123},{"q":"ماذا يترتب على قيام النظام الدولي على قطبية متعددة بحسب الكتاب؟","o":["يصعب التحليل لتلاعب الدول بالتوازنات","يقل تمرد الدول الصغيرة والمتوسطة","تصبح الحرب المباشرة بين الكبار أمرا حتميا","يزول أثر صانع القرار في سلوك دولته"],"why":"وإذا كان النظام الدولي قائمًا على قطبية متعددة فإنَّ ذلك يعزز من تلاعب الدول بتوازنات القوى في النظام الدولي، مما يعقّد عملية التحليل السياسي.","pg":130}]},{"k":"c5","t":"الفصل الخامس: الأمم المتحدة (المدرّب)","q":"كيف نشأت الأمم المتحدة، وكيف تعمل أجهزتها، وما الذي يؤخذ عليها؟","essence":"مدرب دولي تقوده قوة الخمسة الكبار","kw":["مجلس الأمن","حق النقض","الفصل السابع"],"sections":[{"t":"السياق التاريخي","pg":139,"key":"وفي كلتا الحالتين نلاحظ أنَّ إنشاء المنظمّات المعنيَّة بالسلام الدولي يأتي باعتباره ردّة فعل وليس فعلاً ابتدائياً من قبل الدول","p":["فهي لا تنشأ للوقاية من وقوع الحروب، وإنما للوقاية من تكرارها."],"items":[{"h":"عصبة الأمم","x":"ولدت فكرتها من الرئيس ويلسون بعد الحرب الأولى، ولم تشارك فيها الولايات المتحدة لرفض مجلس الشيوخ معاهدة فرساي."},{"h":"فشل العصبة","x":"تجاهلتها اليابان في منشوريا وموسوليني في الحبشة وهتلر في رينانيا، ثم طرد الاتحاد السوفيتي بعد غزو فنلندا عام 1939."},{"h":"الأمم المتحدة","x":"أنشئت للسبب نفسه بعد كوارث الحرب العالمية الثانية."}]},{"t":"مجلس الأمن: العضوية والتصويت","pg":141,"key":"هو الجهاز الذي يشكّل الذراع العسكري والتنفيذي للأمم المتحدة.","p":["وهذا هو الإصلاح الوحيد واليتيم الذي عرفه مجلس الأمن منذ تأسيسه."],"items":[{"h":"الأجهزة الستة","x":"الجمعية العامة، ومجلس الأمن، والمجلس الاقتصادي والاجتماعي، ومجلس الوصاية المعلق منذ 1994، ومحكمة العدل الدولية، والأمانة العامة."},{"h":"العضوية","x":"زاد الأعضاء عام 1965 من أحد عشر إلى خمسة عشر: خمسة دائمون يملكون حق النقض، وعشرة يتغيرون كل سنتين."},{"h":"التصويت","x":"المسائل الإجرائية بتسعة أصوات دون تمييز، والموضوعية بتسعة يكون منها الدائمون جميعا، ومعيار التفريق عند المؤلف: سؤال ما للموضوعي، وسؤال كيف للإجرائي."},{"h":"الامتناع","x":"يجب على العضو الطرف في النزاع أن يمتنع عن التصويت، كما فعلت فرنسا في طلب لبنان وسوريا."}]},{"t":"حفظ السلم بين الفصلين السادس والسابع","pg":153,"key":"ففي الفصل السادس يتصرَّف مجلس الأمن على أنه \"مُصلِح\"، أما إذا تصرّف وفقاً للفصل السابع فهو يتصرّف بوصفه \"رادعاً\" للطرف المتسبب بالنزاع.","p":["فإنَّ الفصل السابع يُتيح لمجلس الأمن أن يجنح إلى العقوبات القاسية، ابتداءً من المقاطعة الاقتصادية والدبلوماسية وانتهاءً بالحلول العسكرية."],"items":[{"h":"الطرق الاستطلاعية","x":"لجان تحقيق تنقل الواقع فقط، ولجان توفيق تقترح الحل."},{"h":"الطرق الدبلوماسية","x":"المفاوضات بين أطراف النزاع، والوساطة التي يشارك فيها الطرف الثالث في الحل كاتفاق الطائف، والمساعي الحميدة التي تعيد الأطراف إلى التفاوض فقط كمسعى عمان."},{"h":"الطرق القضائية","x":"التحكيم بقضاة تختارهم الدول وحكمه ملزم نهائي، والقضاء الدولي كمحكمة العدل والمحكمة الجنائية الدولية الدائمة."},{"h":"حد الفصل السادس","x":"قراراته غير ملزمة، ولذلك لم ينفذ القرار 242."},{"h":"مراحل الفصل السابع","x":"التحقق، ثم التهدئة، ثم العقوبات التي لا تكون إلا بموافقة الدائمين."}]},{"t":"الجمعية العامة وبقية الأجهزة","pg":161,"key":"جاءت الجمعيَّة العامة لتكون منبراً عاماً تُعبّر فيه جميع دول العالم","p":["فبإمكان أي دولة في العالم تنتمي إلى الأمم المتحدة أن تعرض قضيتها في هذا المنبر."],"items":[{"h":"قرارات الجمعية","x":"أغلبية الثلثين في القضايا الجوهرية كالسلم والميزانية وقبول الأعضاء، والأغلبية المطلقة في غيرها."},{"h":"الأمانة العامة","x":"جهاز التنسيق والإشراف، يرأسه الأمين العام الذي تعينه الجمعية بتوصية من مجلس الأمن، ووصفه تريجفي لي بأصعب وظيفة على وجه الأرض."},{"h":"المجلس الاقتصادي والاجتماعي","x":"أربعة وخمسون عضوا، لكل عضو صوت واحد، وأعماله استشارية في أغلبها."},{"h":"محكمة العدل الدولية","x":"الذراع القضائي، خمسة عشر قاضيا، ولا ترفع أمامها الدعاوى إلا من الدول."}]},{"t":"الانتقادات الموجهة لمجلس الأمن والأمم المتحدة","pg":159,"key":"فلا يصحُّ أن نجعل أمرًا نسبيًا متغيّرًا معيارًا لأمر مطلق لا يتغيّر.","p":["الانتقاد الثالث: أنَّ العقوبات التي يفرضها مجلس الأمن تخالف مبادئ حقوق الإنسان؛ لأنها عقوبات جماعية تضر بالمجتمع بأكمله، وليس بالأفراد المسؤولين"],"items":[{"h":"مناقضة الديمقراطية","x":"لا مساواة بين الدول في التصويت، والأعضاء الدائمون لم ينتخبوا، والمجلس يقوم على حكم الأقلية. ويقابل ذلك رأي لاسكي في منح الكبار سلطانا خاصا."},{"h":"العضوية المطلقة","x":"بقاء الخمسة مرتبط بقوة نسبية متغيرة، والقوة لا تصلح معيارا لعضوية دائمة."},{"h":"التمثيل والسلطة التقديرية","x":"لا تمثيل لأفريقيا وأمريكا الجنوبية، وانفراد المجلس بتقدير ما يهدد السلم يخضعه لأهواء الخمسة."},{"h":"نقد الأمم المتحدة عموما","x":"العجز عن حفظ السلم، والتبعية للسياسة الأمريكية، وقيامها على تحالف المنتصرين، والفساد كما في برنامج النفط مقابل الغذاء."}]}],"quiz":[{"q":"جمعت سلطنة عُمان مفاوضي إيران والولايات المتحدة في مسقط لتعيدهم إلى الطاولة، دون أن تشارك في التفاوض. كيف يصنف عملها؟","o":["مساعٍ حميدة","وساطة دولية","تحكيم دولي","لجنة توفيقية"],"why":"كانت مساعي حميدة، لماذا؟ لأنها لم تشارك في المفاوضات ولم تسعَ لتقديم حلولٍ لخلافات الأطراف","pg":148},{"q":"لماذا لم ينفذ القرار 242 الداعي إلى الانسحاب من الأراضي المحتلة عام 1967 بحسب الكتاب؟","o":["لأنه صدر وفق الفصل السادس فلم يكن ملزما","لأن روسيا والصين استعملتا حق النقض ضده","لأن الجمعية العامة رفضته بأغلبية الثلثين","لأنه صدر عن محكمة العدل لا عن المجلس"],"why":"لأنه صدر وفقاً للفصل السادس وليس الفصل السابع","pg":152},{"q":"كيف يتخذ مجلس الأمن قراره في مسألة موضوعية؟","o":["بتسعة أصوات منها الأعضاء الدائمون جميعا","بتسعة أصوات دون تمييز بين الأعضاء","بأغلبية ثلثي الأعضاء الخمسة عشر","بإجماع الأعضاء الخمسة عشر كلهم"],"why":"فإنَّ القرار يُتخذ بموافقة تسعة أعضاء على الأقل شريطة أن يكون جميع الأعضاء الدائمين من الأعضاء التسعة المصوّتين","pg":142},{"q":"ما الخلل المنطقي الذي يأخذه الكتاب على بقاء الأعضاء الخمسة الدائمين؟","o":["أنه يجعل القوة النسبية معيارا لعضوية مطلقة","أنه يمنح الجمعية العامة سلطة ملزمة للدول","أنه يقصر حق التقاضي الدولي على الأفراد وحدهم","أنه يلزم المجلس بالعمل وفق الفصل السادس"],"why":"فلا يصحُّ أن نجعل أمرًا نسبيًا متغيّرًا معيارًا لأمر مطلق لا يتغيّر.","pg":159},{"q":"شركة بريطانية خاصة أرادت مقاضاة دولة أمام محكمة العدل الدولية. ما مصير دعواها؟","o":["لا تنظر فيها لأن الأطراف دول فقط","تنظر فيها إن تعلقت بتفسير معاهدة","تنظر فيها إن تكفلت الشركة بالأتعاب","تحيلها إلى مجلس الأمن ليقرر فيها"],"why":"للدول وحدها الحق في أن تكون أطرافاً في الدعاوى التي ترفع للمحكمة","pg":167}]},{"k":"c6","t":"الفصل السادس: القانون الدولي (الحكم)","q":"ما القانون الدولي، ومن أين يستمد أحكامه، ولماذا يضعف تطبيقه؟","essence":"حكم دولي ينقصه الجزاء الفعال","kw":["المعاهدات","العرف الدولي","الجزاء الفعال"],"sections":[{"t":"مقدمات: النشأة والموقع والأهمية","pg":177,"key":"وهذا يقودنا إلى القول إنَّ القانون الدولي أصلاً لم يولد إلا بعد ميلاد الدول؛ لأنَّه مرتبطٌ بها ولازمٌ لها.","p":["أولاً: يكون مرجعيّة عليا حين تختلف الدول فيما بينها."],"items":[{"h":"النشأة","x":"يؤرخ أغلب الفقهاء ميلاده المعاصر بمعاهدة ويستفاليا 1648، ومن يشترط الجزاء الفعال يجعله يبدأ بتأسيس الأمم المتحدة."},{"h":"موقعه","x":"القانون العام ما كانت الدولة طرفا فيه بصفتها السيادية، والخاص ما ليس كذلك، والقانون الدولي العام من فروع القانون العام."},{"h":"أهميته","x":"مرجعية عند الاختلاف، وحماية لحقوق الدول والمنظمات، وشرعنة لاستعمال القوة أو تجريمه."}]},{"t":"تعريف القانون الدولي","pg":179,"key":"إذن القانون الدولي في عصرنا الحديث هو مجموعة القواعد التي تنظم عملية التفاعل بين الفاعلين الدوليين.","p":["نلاحظ على هذا التعريف أنه غيرُ مقتصر على عنصر الدولة فقط، وإنّما شامل لكل أشخاص القانون الدولي."],"items":[{"h":"مرحلتان","x":"تعريفه بأنه قواعد تنظم العلاقات بين الدول ينتمي إلى مرحلة الدولة لاعبا وحيدا، والتعريف الحديث يدخل المنظمات والشركات."},{"h":"حدوده","x":"لا يعنى بتنظيم الشأن الداخلي للدول كمسألة الجنسية."}]},{"t":"مصادر القانون الدولي","pg":180,"key":"مصادر أصلية: وهي: المعاهدات الدولية والعُرف الدولي ومبادئ القانون العامة","p":["الأمر ليس كذلك، فالقانون الدولي له عدة مصادر، وهي قسمان"],"items":[{"h":"المعاهدات","x":"أكثر المصادر أثرا، وإلزامها لا يتجاوز أطرافها، ومزاياها الاستقرار وسد ثغرات العرف وسرعة الإنشاء."},{"h":"العرف الدولي","x":"له ركن مادي هو سلوك عام مطرد، وركن معنوي هو الشعور بالإلزام، ومثاله عرف تقاسم أرباح النفط مناصفة."},{"h":"مبادئ القانون العامة","x":"مبادئ مسلمة عند الأمم المتمدنة، يلجأ إليها مرحلة ثالثة بعد المعاهدات والعرف."},{"h":"المصادر الثانوية","x":"الأحكام القضائية الدولية والمحلية بشروط، ومذاهب كبار المؤلفين في القانون الدولي العام."}]},{"t":"الانتقادات الموجهة إلى القانون الدولي","pg":191,"key":"وغياب الجزاء الفعال يسلب التشريع الطبيعة القانونية، ويجعله بمثابة توصيات.","p":["التشريع لا يكون قانونًا إلا إذا كانت هناك سلطة قادرة على فرضه."],"items":[{"h":"أزمة التطبيق","x":"القوى الكبرى تتجاوز القانون حين تخالف مصالحها، فيصير قناعا للأقوياء كما يقول تشومسكي."},{"h":"ازدواجية المعاملة","x":"عوقبت جنوب أفريقيا حتى تركت الفصل العنصري، ولم تقابل انتهاكات الكيان الصهيوني بعقوبات جادة."},{"h":"الإشكال الجوهري","x":"لا سلطة تفرض القانون الدولي، ولذلك شكك بعض القانونيين في طبيعته القانونية."}]}],"quiz":[{"q":"باعت دولة قطعة أرض لأحد مواطنيها بعقد بيع عادي. أي قانون ينظم هذه العلاقة؟","o":["القانون الخاص لأنها لم تتصرف بصفتها السيادية","القانون العام لأن الدولة طرف في هذه العلاقة","القانون الدولي العام لأنه يحكم تصرفات الدول","القانون الدستوري لأنه ينظم سلطات الدولة"],"why":"فالدولة إذا مارست البيع والشراء مع المواطنين فإنها هنا لا تتصرف بوصفها السيادي، وإنما بوصفها العادي","pg":176},{"q":"عقدت إيران وتركيا اتفاقا ثنائيا. هل يلزم باكستان؟","o":["لا، عملا بقاعدة نسبية أثر المعاهدات","نعم، لأن المعاهدات مصدر أصلي ملزم","نعم، ما دامت باكستان دولة مجاورة لهما","لا، لأن المعاهدات مصدر ثانوي فقط"],"why":"فإذا حصلت مثلاً معاهدة بين إيران وتركيا فهي ليست بملزمة لباكستان.","pg":181},{"q":"ما الركنان اللذان يتكون منهما العرف الدولي؟","o":["سلوك عام مطرد وشعور بالإلزام به","معاهدة مكتوبة وتصديق برلماني عليها","حكم قضائي سابق ورأي كبار الفقهاء","قرار من مجلس الأمن وتنفيذ الدول له"],"why":"الركن الثاني: ركنٌ معنوي، وهو أن ينشأ شعورٌ بالإلزام تجاه هذا الفعل","pg":183},{"q":"متى يلجأ القاضي الدولي إلى مبادئ القانون العامة؟","o":["حين لا يجد حكما في المعاهدات والعرف","قبل النظر في المعاهدات والعرف الدولي","حين يختلف القضاة في الأحكام السابقة","حين تختلف ترجمات النظام الأساسي"],"why":"وإنما تأتي بوصفها مرحلةً ثالثة في حال عدم وجود قوانين ناشئة عن المعاهدات","pg":184},{"q":"ما الإشكال الذي تتفرع عنه إشكالات عدم تطبيق القانون الدولي بحسب الكتاب؟","o":["أنه لا يمتلك سلطة تفرضه","غموض نصوصه وتعدد ترجماته","كثرة مصادره الأصلية والثانوية","اقتصاره على تنظيم شؤون الدول"],"why":"فإن الإشكال الجوهري الذي تتفرع منه إشكالات عدم تطبيق القانون الدولي هو أنه لا يمتلك سلطة تفرضه","pg":190}]},{"k":"c7","t":"الفصل السابع: إدارة الصراع الدولي","q":"كيف توازن الدول قواها، وكيف تدير صراعاتها سلما وحربا؟","essence":"التوازن يمنع الحرب والتفاوض يدير الصراع","kw":["توازن القوى","التفاوض","الردع"],"sections":[{"t":"توازن القوى","pg":201,"key":"القاعدة السياسية التاريخية هي أن الحرب عادةً تبدأ من ذات النقطة التي ينتهي عندها توازن القوى.","p":["فحينما يكون هناك توازن في القوى في النظام الدولي فإنَّ حالة السِّلم تكون سائدةً"],"items":[{"h":"التعريف الإجرائي","x":"النتيجة المترتبة على سعي دولة أو تحالف إلى قوة توازي قوة الخصم بهدف ردعه."},{"h":"أسبقية الفارابي","x":"يرد المؤلف على من جعل الفكرة تبدأ من القرن الخامس عشر بنص الفارابي في القرن التاسع الميلادي، وبإشارة القرآن."},{"h":"كسر التوازن","x":"من أراد أن يكون الأقوى استثار تحالف الآخرين ضده، كما جرى لنابليون وهتلر، وكما يرى المؤلف في حال الولايات المتحدة."},{"h":"طرق تحقيقه","x":"البناء الذاتي، والبناء المشترك بالتحالف، والتبعية السياسية لدولة أقوى."}]},{"t":"الصراع السلمي: التفاوض","pg":212,"key":"إنَّ معيار نجاح أية عملية تفاوض هو تحقيق أكبر قدر من المكاسب وتقليل التنازلات","p":["إذن من شروط التفاوض أن يكون لدى الطرفين خيارات متعددة، بحيث يمكن لهما التناور والتحاور وتقديم التنازلات وجني المكاسب."],"items":[{"h":"المتطلبات الثلاثة","x":"الاستعداد لتقديم تنازلات، كتنازلات النبي صلى الله عليه وسلم في صلح الحديبية، وامتلاك القدرة على التنفيذ، وتعدد الخيارات."},{"h":"وضوح الهدف والتدرج","x":"أن يعرف المفاوض هدفه، وأن يرتب أهدافه في سلم أولويات."},{"h":"الخطوط الحمراء والأرض","x":"أن يوضح ما لا يقبل التفاوض، وأن يحسن وضعه على الأرض قبل الدخول."},{"h":"التشتيت والزمن","x":"تحويل هدف المفاوضات إلى ما يخدمه، واستغلال الوقت إطالة أو تحديدا."},{"h":"حفظ ماء الوجه والوضوح","x":"ألا يخرج الخصم خاوي اليدين، وأن يتجنب الألفاظ الضبابية كلفظ الإرهاب دون تعريف."},{"h":"الخلفية والقدرات","x":"معرفة خلفيات الطرف الآخر، والذكاء الشخصي في المناورة، كما في قصة التحكيم بين عمرو بن العاص وأبي موسى الأشعري."}]},{"t":"الصراع السلمي: المساومة","pg":220,"key":"المساومة هي عمليّة تحاوريّة بين طرفين غير متساويين باستعمال آلية التهديد لكن دون إجبار.","p":["أي أن تقوم دولة باستغلال حاجة دولةٍ أخرى لتحقيق مكاسب منها من خلال تقديم عرض لها لمدة محددة في حال عدم تلبيتها لهذا العرض فإنَّها تكون مهددة بخسارةٍ أكبر."],"items":[{"h":"مثال","x":"الحصار المفروض على العراق ومساومته على غذاء شعبه مقابل النفط."},{"h":"من حيث الآلية","x":"التفاوض حوار قائم على الندية، والمساومة تهديد واستغلال."},{"h":"من حيث المستوى والمدة","x":"التفاوض بين متعادلين وطويل الأمد، والمساومة بين غير متعادلين وقصيرة الأمد."}]},{"t":"الصراع العسكري: التصعيد والردع","pg":228,"key":"الردع هو أن تقوم الدولة المهدَّدة بتقديم أدلة يقينية بأنها قادرة على الثأر والرد","p":["فالتصعيد هو أن تزيد دولة في فعلها السياسي أو العسكري في إطار خصومة مع دولة أخرى"],"items":[{"h":"شرط التصعيد","x":"وجود خصومة بين البلدين، والأصل الرد بتصعيد مماثل إلا إذا خيفت العواقب أو كان التجاهل أنجع."},{"h":"أهداف التصعيد","x":"دفع خطر محتمل، والتنفيس عن ضغط داخلي، والتصعيد بالوكالة، والرغبة في مكاسب اقتصادية."},{"h":"نهاية التصعيد","x":"زوال سببه، أو إعادة تعريف المصالح، أو توقف أحد الطرفين أو انهياره."},{"h":"صور الردع","x":"المتبادل الذي يصل إلى توازن الرعب، والمتدرج الذي لا يبدأ بأقوى الخيارات، والتدميري الذي يستعمل أقصى القوة."}]},{"t":"الصراع العسكري: الحرب","pg":233,"key":"واختصارًا نقول إنه يمكن أن نعرّف الحرب بأنها: \"قتال بين وحدات سياسية في أكثر من دولة\".","p":["يبدو للوهلة الأولى أن تعريف الحرب واضحٌ وبدهي، لكن في الحقيقة تعريف الحرب أمر ليس باليسير"],"items":[{"h":"قيود التعريف","x":"وحدات سياسية ليشمل ما قبل الدولة والحرب مع الجماعات، وفي أكثر من دولة ليخرج الحروب الأهلية، ولا يشترط الإعلان ولا عدد محدد من القتلى."},{"h":"أسباب الحروب عند ليبو","x":"الأمن والمكانة والانتقام والمصلحة، والمكانة أهمها: اثنتان وستون حربا من أربع وتسعين."},{"h":"المساوئ والفائدة","x":"ضياع المال وفقد الرجال وضعف الشعوب، وقد توحد الروح القومية لكنها ليست ثمنا مناسبا للحرب."},{"h":"أنواعها","x":"محدودة في المكان والسلاح كحرب فيتنام، ومفتوحة كالحربين العالميتين."},{"h":"المشروعية","x":"الميثاق يجيزها للدفاع عن النفس ولمواجهة تهديد السلم بقرار من مجلس الأمن، وفي الإسلام ثلاث حالات سبق بيانها."}]}],"quiz":[{"q":"دولة لا تقدر وحدها على مجاراة خصمها عسكريا، فتحالفت مع جيرانها لتوازنه. أي طريقة لتحقيق التوازن اتبعت؟","o":["البناء المشترك","البناء الذاتي","التبعية السياسية","الردع المتبادل"],"why":"بأن تكون الدولة غير قادرة بمفردها على تحقيق توازن القوى مع خصمها بمفردها، فتضطر إلى الاستعانة بدولٍ أخرى لتشكيل تحالف","pg":204},{"q":"في أزمة الصواريخ الكوبية تعهد كيندي بعدم غزو كوبا مقابل سحب الصواريخ السوفيتية. أي قاعدة تفاوضية يمثلها ذلك؟","o":["تجنب إخراج الخصم خاوي اليدين","استغلال الزمن وإطالة التفاوض","تحسين الوضع على الأرض أولا","تشتيت أهداف المفاوضات الأصلية"],"why":"في جميع أنواع المفاوضات لا بد من المحافظة على ماء وجه المتفاوضين","pg":216},{"q":"ما الذي يميز المساومة من التفاوض في آليتها ومستوى طرفيها؟","o":["التهديد بين طرفين غير متعادلين","الحوار بين طرفين متعادلين","فرض حل قضائي ملزم على الطرفين معا","تبادل المصالح على مدى طويل"],"why":"في حين المساومة تقوم على آلية التهديد والاستغلال.","pg":221},{"q":"أجرت دولة تجارب صاروخية فعدّت تصعيدا ضد جارة بعينها لا ضد جيرانها الآخرين. لماذا؟","o":["لوجود خصومة قائمة بينها وبين تلك الجارة","لأن بقية الجيران لا يملكون أسلحة نووية","لأن التصعيد لا يكون إلا بين قوتين كبريين","لأن تلك الجارة أعلنت الحرب عليها مسبقا"],"why":"الجواب أنَّ من شروط اعتبار التصعيد أن تكون هناك خصومة بين البلدين","pg":223},{"q":"ما أكثر دوافع الحروب حضورا في استقراء ريتشارد ليبو لأربع وتسعين حربا؟","o":["دافع المكانة","دافع الأمن","دافع المصلحة","دافع الانتقام"],"why":"وبخصوص دافع \"المكانة\" فإنه يرى أنَّه أهم دوافع الحروب إطلاقًا","pg":235}]},{"k":"c8","t":"الفصل الثامن: النظريات الدولية","q":"ما الذي ينبغي أن يكون عليه المجتمع الدولي حتى يتحقق السلم؟","essence":"من السلام الديمقراطي إلى الذراع الرادعة","kw":["السلام الديمقراطي","الحكومة العالمية","الذراع الرادعة"],"sections":[{"t":"نظرية السلام الديمقراطي","pg":247,"key":"المبدأ الأول: أن الدول الديمقراطية لا تتقاتل فيما بينها، ولم يشهد التاريخ حربًا بين دولتين ديمقراطيتين.","p":["السبب الأول: أنَّ قرار الحرب في الدول الديمقراطية ليس سهلاً كالدول غير الديمقراطية"],"items":[{"h":"الأصل","x":"تعود إلى مقالة الفيلسوف الألماني كانط في السلام الدائم."},{"h":"أسباب السلم بين الديمقراطيات","x":"صعوبة قرار الحرب لمروره بالمؤسسات، والوعي الشعبي، والثقة المتبادلة، ونقل الآليات الديمقراطية إلى الخارج."},{"h":"المبدأ الثاني","x":"العلاقات خارج المنطقة الديمقراطية صراعية، فالنظرية لا تصلح للعولمة."},{"h":"حضورها اليوم","x":"لا تزال حية في العقل الأمريكي، وتعد تعزيز الديمقراطية أفضل حل لجلب السلام عبر الحدود."}]},{"t":"مناقشة نظرية السلام الديمقراطي","pg":251,"key":"فعدم الوقوع لا يستلزم امتناع العدم","p":["أي أنه لا يوجد تلازم عقلي ولا عرفي بين وجود النظام الديمقراطي وانعدام الحروب"],"items":[{"h":"نقض الدليل التاريخي","x":"انقلاب الولايات المتحدة على حكومة منتخبة في إيران عام 1953."},{"h":"ضيق المجال","x":"تسكت عن حروب الديمقراطيات على غيرها، كما في الجزائر وفيتنام والعراق، وقد تحولت إلى حرب ديمقراطية."},{"h":"لا تلازم","x":"غياب الحرب قد يكون لدواع أخرى، ولم تتحارب الدول الشيوعية فهل يثبت ذلك صحة مبادئها؟"},{"h":"نسبية المفهوم","x":"الديمقراطية نفسها مختلف في مدلولها بين الليبراليين والاشتراكيين."},{"h":"الآليات في الخارج","x":"تطبق الديمقراطيات معاييرها داخليا وتجنح إلى الحل العسكري خارجيا."}]},{"t":"نظرية الذراع الرادعة","pg":261,"key":"هذا الخيار هو الخيار الوحيد الذي يمكن أن يوفّر حالة سلمية مطّردة إلى أقصى درجة ممكنة","p":["الجواب: لأنَّ امتلاك القوة الرادعة حكرٌ على كيان واحد، وهو السلطة التنفيذية، فهي الكيان الوحيد الذي له الحق في امتلاك أدوات القوة والعنف واحتكارها."],"items":[{"h":"بديل عن نظريتين","x":"يرى المؤلف أن السلام الديمقراطي مؤدلج، وأن الحكومة العالمية مثالية تستلزم تنازل الدول عن سيادتها. والنظرية من اقتراح المؤلف نفسه."},{"h":"الفرضيات الثلاث","x":"علاقة طردية بين توازن القوى والسلم، واحتكار القوة الرادعة يقلص العنف دوليا كما يقلصه داخل الدولة، ومجلس الأمن بتركيبته الحالية لا يصلح."},{"h":"الخيارات الأربعة","x":"توازن شامل مكلف ولن تسمح به الكبرى، ونزع شامل للسلاح مثالي، وتوازن بين الكبار يبقي حروب الوكالة، وتجريد الكبار من النووي وحصره في كيان واحد."},{"h":"شرطا مجلس الأمن","x":"أن يحتكر السلاح النووي، وأن تعاد هيكلته ليقوم على المساواة لا على امتيازات الخمسة."}]}],"quiz":[{"q":"فرّق الكتاب بين النظرية الدولية والتحليل الدولي. ما الفرق بينهما؟","o":["النظرية معيارية والتحليل وصفي","النظرية وصفية والتحليل معياري","كلاهما يصف ما هو كائن في الواقع فقط","النظرية مدرسة والتحليل قضية"],"why":"فالنظرية إذن معيارية","pg":7},{"q":"يحتج أنصار السلام الديمقراطي بأن ديمقراطيتين لم تتحاربا قط. بم رد الكتاب على هذا الاستدلال؟","o":["قد تكون هناك دواع أخرى صرفتها عن الحرب","الديمقراطيات تتحارب فيما بينها كل عقد","الحرب لا تقع إلا بين الدول الدكتاتورية","الديمقراطية لا تملك آليات لحل الخلاف"],"why":"فقد تكون هناك دواعٍ أخرى صرفت الدول الديمقراطية عن الحرب غير مسألة طبيعتها الديمقراطية.","pg":251},{"q":"على أي قياس تبني نظرية الذراع الرادعة تصورها لحفظ السلم الدولي؟","o":["احتكار الدولة للقوة داخل حدودها","نشر الديمقراطية في جميع الدول","قيام حكومة عالمية واحدة تحكم البشر","توازن القوى بين الكبار وحدهم"],"why":"تماما كما أن احتكار الدولة للقوة الرادعة يقلص دائرة العنف في المجتمع المحلي.","pg":256},{"q":"لماذا لا يكفي في نظر الكتاب أن يتحقق توازن القوى بين القوى الكبرى وحدها؟","o":["لأن حروب الوكالة تستمر بين أتباعها","لأنه مكلف اقتصاديا للدول الفقيرة","لأنه خيار مثالي بعيد المنال حاضرا","لأنه يلزم الدول بالتنازل عن سيادتها"],"why":"وبعد ذلك يُفتح الباب على مصارعه لقيام الحروب بالوكالات.","pg":261},{"q":"ما الشرطان اللذان يجعلان مجلس الأمن صالحا لاحتضان الذراع الرادعة؟","o":["احتكاره السلاح النووي وإعادة هيكلته","توسيع عضويته الدائمة وزيادة ميزانيته","إلغاء الفصل السابع ونقل صلاحياته","اختيار أعضائه من الدول الخمس وحدها"],"why":"الشرط الأول: أن يكون امتلاك السلاح النووي حكرًا على مجلس الأمن بوصفه الذراع العسكري لهيئة الأمم المتحدة","pg":263}]},{"k":"c9","t":"الفصل التاسع: التحليلات الدولية","q":"كيف قرأ المفكرون عالم ما بعد الحرب الباردة، وما قيمة قراءاتهم؟","essence":"صدام الحضارات ونهاية التاريخ في الميزان","kw":["صدام الحضارات","المهدي المنجرة","نهاية التاريخ"],"sections":[{"t":"صدام الحضارات: الفكرة وصاحبها","pg":267,"key":"كلتا المقاربتين تستند إلى فكرة انتقال منطلقات الحروب من حيِّز المصالح المادية إلى حيِّز أوسع وأشمل وهو حيّز المصالح الحضارية الكبرى.","p":["إذًا هناك رؤية واضحة بأن المهدي المنجرة هو صاحب فكرة صدام الحضارات"],"items":[{"h":"صاحب الفكرة","x":"أقر هنتغتون بأنه أخذ أصلها من المنجرة، لكنها اشتهرت باسمه لأنه فصّلها أكثر."},{"h":"الحضارات عند هنتغتون","x":"ثماني حضارات، اثنتان منها قادرتان على مواجهة الغرب: الإسلامية والصينية."},{"h":"الركيزتان","x":"النظرية بديل عن الواقعية بعد انتقال الصراع من الدول إلى الحضارات، وهي مطلقة مكانا نسبية زمانا."}]},{"t":"بين المنجرة وهنتغتون","pg":270,"key":"الجامع الأول: أهم جامع مشترك بين المنجرة وهنتغتون أنَّ كليهما يتحدث عن تحوِّل جوهري في مسوِّغات الحروب","p":["فقد كانت مسوِّغات الحروب سابقاً تتجسّد في المصالح المادية البحتة"],"items":[{"h":"الجوامع","x":"تحول دوافع الحروب إلى الحضاري، واشتراك نسبي في المؤشرات، واتفاق جزئي على الهوية الدينية للحضارة الغربية."},{"h":"الفروق","x":"المنجرة يرى حضارتين شمالا وجنوبا، ويرد بداية الحرب الحضارية إلى حرب الخليج، وينفي إمكان التعايش، ويحدد لها مدة، ويكتب منظرا للعالم الثالث."},{"h":"قراءة المؤلف","x":"الكتابان قديمان نسبيا، وكتاب المنجرة مقالات متفرقة، وهنتغتون جعل الدين معيارا ولم يطبقه إلا على الإسلام وأهمل اليهودية، والمنجرة بالغ في التضخيم."},{"h":"انهيار لا صدام","x":"يميل المؤلف إلى رأي فرغسون في أن الحضارات مقبلة على انهيار من أمراض داخلية."}]},{"t":"نهاية التاريخ","pg":279,"key":"يقول فوكوياما \"الديمقراطية الليبرالية قد تشكّل نقطة النهاية في التطوّر الإيدلوجي للإنسانية\"","p":["وفوكوياما يرى أنَّه لم يأتِ بجديد في هذه النظرية، وإنما هو امتداد لمن سبقوه"],"items":[{"h":"الفكرة","x":"الديمقراطية الليبرالية والرأسمالية آخر ما ينتجه العقل البشري، وعيوبهما في التطبيق لا في المبدأ."},{"h":"السببان","x":"اقتصادي لأن السوق المفتوحة صنعت رخاء غير مسبوق، وسياسي لأن الديمقراطية صارت مطلبا عالميا ورديفا للحضارة."},{"h":"النقد","x":"لم تلق قبولا، لا سيما مع تراجع القطب الواحد، ووصفها كوكلر بالسطحية، ويرى المؤلف أن تحديد مصير نهائي للوعي ارتهان للحظة التاريخية."}]}],"quiz":[{"q":"من صاحب فكرة صدام الحضارات في أصلها بحسب ما يثبته الكتاب؟","o":["المهدي المنجرة","صموئيل هنتغتون","فرنسيس فوكوياما","نعوم تشومسكي"],"why":"إذًا هناك رؤية واضحة بأن المهدي المنجرة هو صاحب فكرة صدام الحضارات","pg":267},{"q":"ما أهم ما يجمع بين أطروحتي المنجرة وهنتغتون؟","o":["تحول دوافع الحروب إلى الحضارية","اتفاقهما على أن حضارات العالم ثمان","اتفاقهما على إمكان التعايش بين الحضارات","اتفاقهما على مدة الحرب الحضارية"],"why":"أهم جامع مشترك بين المنجرة وهنتغتون أنَّ كليهما يتحدث عن تحوِّل جوهري في مسوِّغات الحروب","pg":270},{"q":"ما الخلل المنهجي الذي أخذه الكتاب على هنتغتون؟","o":["جعل الدين معيارا وطبقه على الإسلام وحده","كتب مقالات متفرقة بلا ترتيب منهجي","بالغ في تضخيم دور حكومة صدام حسين","حدد للحرب الحضارية سقفا زمنيا قصيرا محددا"],"why":"لكنه لم يطبق ذلك إلا على الحضارة الإسلامية","pg":277},{"q":"بم يفسر فوكوياما وجود الظلم والمشكلات في الديمقراطيات الراسخة؟","o":["بقصور في تطبيق مبدأي الحرية والمساواة","بتناقضات أساسية في مبادئها النظرية","بسيطرة الشركات الكبرى على قراراتها","بحتمية زوال الرأسمالية كما قال شومبيتر"],"why":"غير أن هذه المشاكل في ظنّي وليدة قصور في تطبيق المبدأين التوأم: الحرية والمساواة","pg":280},{"q":"لماذا يرى المؤلف أن نقد كوكلر لنظرية نهاية التاريخ لا يخلو من الصواب؟","o":["لأن تحديد مصير نهائي للوعي ارتهان للحظة","لأن الليبرالية أسوأ من الأيدلوجيات السابقة","لأن الرأسمالية لم تحقق أي رخاء مادي","لأن الديمقراطية لم تعد مطلبا للشعوب"],"why":"بل لأصل الفكرة التي تقوم على تحديد مصير معين لمآلات الوعي الإنساني، وهذا لا يعدو كونه ارتهانًا للحظة التاريخية التي نعيشها.","pg":282}]},{"k":"c10","t":"الفصل العاشر: قضايا دولية (الإرهاب أنموذجًا)","q":"لماذا يصعب تعريف الإرهاب، وكيف يوظف في الصراع السياسي؟","essence":"مصطلح فضفاض يسلط سيفا على الخصوم","kw":["الإرهاب","المدنيون","التوظيف السياسي"],"sections":[{"t":"مفهوم الإرهاب","pg":288,"key":"فيكون تعريف الإرهاب المختار هو الاعتداء على المدنيين لتحقيق أغراض سياسية.","p":["فبناءً على هذا التعريف تكون الثورات فعلاً إرهابيًّا؛ لأنها تستعمل العنف لتحقيق غايات سياسية."],"items":[{"h":"صعوبة التعريف","x":"لا أحد يصف نفسه بأنه إرهابي، فيتباين التعريف بتباين معايير من يصف."},{"h":"الدلالة اللغوية والغربية","x":"رهب في العربية مطلق الخوف بحق أو باطل، وتبلور المصطلح الغربي إبان الثورة الفرنسية نحو 1794."},{"h":"تعريفات مختارة","x":"تعريف الجمعية العامة 1994، وتعريف معاهدة منظمة المؤتمر الإسلامي الذي أقرته دول مجلس التعاون، وتعريف أكسفورد الذي يتجاهل إرهاب الدول."},{"h":"الإرهاب في القرآن","x":"في قوله تعالى في سورة الأنفال يأتي بمعنى إعداد القوة لردع من يخشى غدره، فهو وسيلة سلم توازي توازن الرعب."}]},{"t":"أنواع الإرهاب","pg":291,"key":"الإرهاب الدولي هو الفعل الإرهابي الذي له بُعدٌ دولي، فلا يكون مقتصرًا على دولة بعينها، وإنما هو ممتد لعدة دول.","p":["فعلى سبيل المثال نجد أن أحداث الحادي عشر من سبتمبر تنطبق عليها جميع هذه الخصائص، مما يدلُّ على أنها إرهابٌ دولي."],"items":[{"h":"الإرهاب المحلي","x":"يرتكب داخل الدولة، ويشترك مرتكبوه وضحاياه في جنسيتها، وتبقى آثاره داخلها، ولا دعم خارجي له."},{"h":"الإرهاب الدولي","x":"تتعدد فيه الجنسيات أو تختلف، وتمتد آثاره إلى عدة دول، أو يحصل مرتكبوه على دعم خارجي، كأحداث الحادي عشر من سبتمبر."},{"h":"باعتبار الفاعلين","x":"إرهاب أفراد وجماعات كجماعة أرجون الصهيونية، وإرهاب دول كتدمير الطائرات المدنية في مطار بيروت عام 1968."}]},{"t":"الإرهاب وإشكالية التوظيف","pg":294,"key":"فالإرهاب أضحى كالسيف في أيدي المنظمات والحكومات تسلّطه على رقاب من تشاء من خصومها","p":["إن الإشكال الأكبر في موضوع الإرهاب لا تقف عند حدود تعريفه، بل تمتد إلى كيفية توظيفه عبثيًا"],"items":[{"h":"سابقة تاريخية","x":"حاول أنصار الملكية في فرنسا إقناع الشعب بأن اليعاقبة إرهابيون، واستعمله ملوك أوروبا ذريعة لكبح الحراك الثوري."},{"h":"في عصرنا","x":"يرى المؤلف أن الولايات المتحدة أكثر الدول استعمالا للمصطلح مسوغا لسلوكها الهجومي، وأنها نفسها وقعت في ممارسات إرهابية."}]}],"quiz":[{"q":"لماذا رفض المؤلف تعريف الإرهاب بأنه استعمال العنف لتحقيق غايات سياسية؟","o":["لأنه يدخل ثورات التحرر في الإرهاب","لأنه يقصر الإرهاب على الجماعات","لأنه يخالف تعريف الجمعية العامة","لأنه لا يشترط وجود دعم خارجي"],"why":"فبناءً على هذا التعريف تكون الثورات فعلاً إرهابيًّا؛ لأنها تستعمل العنف لتحقيق غايات سياسية.","pg":288},{"q":"ما الذي أخذه الكتاب على تعريف معجم أكسفورد السياسي للإرهاب؟","o":["أنه يتجاهل الإرهاب الذي تمارسه الدول","أنه يجعل ثورات التحرر أعمالا إرهابية","أنه يشترط تعدد جنسيات مرتكبي الفعل","أنه يربط الظاهرة بالدوافع الدينية وحدها"],"why":"فهو يتحدث عن إرهاب المجموعات فقط، ويتجاهل الإرهاب الحاصل من قِبل الدول.","pg":288},{"q":"نفذ مواطنون هجوما داخل دولتهم على مواطنين مثلهم، بلا دعم من الخارج، وبقيت آثاره في حدودها. كيف يصنف؟","o":["إرهاب محلي","إرهاب دولي","إرهاب الدولة","حرب أهلية"],"why":"المقصود بالإرهاب المحلي هو الفعل الإرهابي الذي يُرتكب داخل الدولة، فلا يكون له بُعد دولي.","pg":290},{"q":"كيف يفرق الكتاب بين معنى الإرهاب في القرآن ومعناه في القانون المعاصر؟","o":["الأول وسيلة سلم توازي توازن الرعب","الأول يعني الاعتداء على المدنيين العزل","كلاهما أداة لتقويض السلم الدولي","الأول خاص بقتال الجماعات المسلحة"],"why":"فالإرهاب في القرآن أداة لتحقيق السلم، وفي القانون المعاصرة أداة لتقويض السلم","pg":289},{"q":"بم يعلل الباحث تشارلز تاونشند صعوبة الاتفاق على تعريف الإرهاب؟","o":["بأن أحدا لا يصف نفسه بأنه إرهابي","بأن القانون الدولي لم يذكر المصطلح","بأن المصطلح عربي الأصل لا غربي","بأن الأمم المتحدة منعت تعريفه رسميا"],"why":"إلى أنه لا يوجد أحد يصف نفسه بأنه إرهابي","pg":285}]}],"highlights":[{"x":"فالعدل بلا قوة ضعف، والقوة بلا عدل ظلم.","pg":118},{"x":"قوّة المنطق أم منطق القوة؟","pg":43},{"x":"ولو تركنا لكل شخص حريّة استخدام القوة في حل الخلافات لصار المجتمع فوضى لا نظامَ فيه.","pg":43},{"x":"فالديمقراطية إذن تحفظ حقوق الأغلبية، والليبرالية تحفظ حقوق الأقلية","pg":33},{"x":"فهي لا تنشأ للوقاية من وقوع الحروب، وإنما للوقاية من تكرارها.","pg":139},{"x":"فلا يصحُّ أن نجعل أمرًا نسبيًا متغيّرًا معيارًا لأمر مطلق لا يتغيّر.","pg":159},{"x":"فأي قيمة لقانونٍ لا يُعاقب مخالفُهُ؟","pg":189},{"x":"فالحرب هي إحدى صور الصراع وليست مرادفة له","pg":206},{"x":"فالردع أقوى من التصعيد وأقل من الحرب.","pg":232},{"x":"العلاقات تقوم في الأصل على القهر والغلبة","pg":114}],"concepts":[{"term":"علم العلاقات الدولية","def":"العلم الذي يدرس مكوّنات المجتمع الدولي ذات التأثير السياسي","pg":15},{"term":"الحرب الباردة","def":"وجود حالة صراع بين دولتين أو أكثر دون استعمال أدوات القوة الصلبة المباشرة","pg":33},{"term":"الدولة","def":"السلطة التي تحكم شعبًا محددًا على أرضٍ محددة.","pg":55},{"term":"السيادة","def":"ألا تكون هناك سلطة فوق السلطة الشرعية لا داخليًا ولا خارجيًا.","pg":60},{"term":"الدولة الفاشلة","def":"إذا فقدت دولة سيادتها داخليًّا فإنها تسمى دولة فاشلة؛ أي أنها عاجزة عن فرض إرادتها على جميع أراضيها","pg":60},{"term":"المنظمة الدولية","def":"كيان دولي يؤسس على اتفاق وله شخصية قانونية مستقلة دولية.","pg":68},{"term":"الشخصية القانونية المستقلة","def":"الشخصية القانونية المستقلة تعني القدرة الذاتية على تحصيل الحقوق وتحمّل الالتزامات.","pg":71},{"term":"الشركات متعددة الجنسيات","def":"كيان دولي تجاري خاص له فروع في أكثر من دولتين مرتبطة بالشركة الأم.","pg":80},{"term":"الدولة المهيمنة","def":"الدولة التي تعد الأقوى في النظام الدولي بحيث تهدد هي الدول الأخرى دون أن تستطيع أي دولة تهديدها.","pg":129},{"term":"الوساطة","def":"الوساطة هي جهودٌ يبذلها طرفٌ ثالث لإيجاد حل لنزاعٍ بين عدة أطراف من خلال التفاوض.","pg":147},{"term":"المساعي الحميدة","def":"المساعي الحميدة هي جهود يبذلها طرفٌ ثالث لإقناع أطراف النزاع بالبحث عن حل لنزاعٍ ما أو البدء بالتفاوض المباشر.","pg":148},{"term":"المعاهدات الدولية","def":"كل اتفاق بين شخصين من أشخاص القانون الدولي من شأنه أن يُنتج أثرًا حقوقيًّا","pg":180},{"term":"العرف الدولي","def":"مجموعة من القواعد الناشئة عن تواتر الالتزام بها من قبل الدول في تصرفاتها تجاه بعضها بعضًا","pg":182},{"term":"توازن القوى","def":"النتيجة المترتبة على سعي دولةٍ أو تحالف إلى تكوين قوة توازي قوّة الخصم بهدف ردعه.","pg":197},{"term":"التفاوض","def":"التفاوض هو حوارٌ بين طرفين أو أكثر يهدف إلى إيجاد تسويات سياسية في مصلحة الطرفين.","pg":208},{"term":"المساومة","def":"المساومة هي عمليّة تحاوريّة بين طرفين غير متساويين باستعمال آلية التهديد لكن دون إجبار.","pg":220},{"term":"التصعيد","def":"التصعيد هو أن تعمد إحدى الدول إلى زيادة في الفعل السياسي أو العسكري في مرحلة خصومة مع دولة أخرى.","pg":223},{"term":"الردع","def":"الردع هو أن تقوم الدولة المهدَّدة بتقديم أدلة يقينية بأنها قادرة على الثأر والرد","pg":228},{"term":"الحرب","def":"قتال بين وحدات سياسية في أكثر من دولة","pg":233},{"term":"الإرهاب","def":"الاعتداء على المدنيين لتحقيق أغراض سياسية.","pg":288}],"links":[{"topic":"السيادة","pg":40},{"topic":"الحرب الباردة","pg":33},{"topic":"الثورة الفرنسية","pg":22},{"topic":"الدولة","pg":51},{"topic":"الأمم المتحدة","pg":135},{"topic":"التفاوض","pg":208},{"topic":"الحرب","pg":232},{"topic":"الديمقراطية","pg":247},{"topic":"الإرهاب","pg":285},{"topic":"الموقف الإسلامي من العلاقات الدولية","pg":112}]};
